def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Return one priority for each feasible bin.

    ``bins`` contains remaining capacities after filtering bins that cannot
    hold ``item``.  The evaluator selects the first maximum priority and
    opens a new bin when the array is empty.
    """
    residual = bins - item
    # Prefer bins where the post-placement residual is small but not zero;
    # approximate best-fit with a mild preference against leaving tiny gaps.
    return -residual / (bins + item + 1e-12)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return -remaining - 0.01 * (remaining / (bins + 1.0)) ** 2
